const item = $input.first().json;
const msg = (item.errorMessage || '').toLowerCase();
let category = 'unknown';
if (msg.includes('rate limit') || msg.includes('429')) category = 'rate_limit';
else if (msg.includes('timeout') || msg.includes('econnaborted')) category = 'timeout';
else if (msg.includes('5') && msg.match(/5\d\d/)) category = 'server_error';
else if (msg.includes('401') || msg.includes('403')) category = 'auth';
else if (msg.includes('validation') || msg.includes('400')) category = 'validation';

const retryable = ['rate_limit','timeout','server_error'].includes(category);
const maxRetries = category === 'rate_limit' ? 3 : 2;

return [{ json: { ...item, errorCategory: category, retryable, maxRetries } }];

